package resforge.audio;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

class OggVorbisDecodeTests {

    private static final String SAMPLE_RESOURCE = "vorbis-sample.ogg";
    private static final int SAMPLE_RATE = 44100;
    private static final int SAMPLE_CHANNELS = 2;
    private static final int SAMPLE_PCM_BYTES = 417480;
    private static final int SAMPLE_FRAMES = 104370;
    private static final int TEST_SERIAL = 0x18273645;

    @Test
    void decodesVorbisSampleToExpectedInterleavedPcm() throws IOException {
        OggVorbis.Pcm pcm = OggVorbis.decode(readSample());

        assertEquals(SAMPLE_RATE, pcm.rate);
        assertEquals(SAMPLE_CHANNELS, pcm.channels);
        assertEquals(SAMPLE_PCM_BYTES, pcm.data.length);
        assertEquals(SAMPLE_FRAMES, pcm.frames());
        assertEquals(SAMPLE_FRAMES / (double) SAMPLE_RATE, pcm.seconds(), 1.0e-12);
        assertEquals(0, pcm.data.length % (pcm.channels * 2));

        // First eight little-endian signed 16-bit samples, alternating L/R.
        assertArrayEquals(
                new byte[] {
                        (byte) 0xd2, (byte) 0xff, (byte) 0x9c, (byte) 0x01,
                        (byte) 0x06, (byte) 0x00, (byte) 0xcc, (byte) 0x01,
                        (byte) 0xd1, (byte) 0xff, (byte) 0x9d, (byte) 0x02,
                        (byte) 0xbc, (byte) 0xff, (byte) 0x48, (byte) 0x02
                },
                Arrays.copyOf(pcm.data, 16));
    }

    @Test
    void acceptsStreamThatEndsAfterTheVorbisHeadersAndReturnsNoSamples() throws IOException {
        byte[] sample = readSample();
        int endOfHeaders = endOfPage(sample, 1);

        OggVorbis.Pcm pcm = OggVorbis.decode(Arrays.copyOf(sample, endOfHeaders));

        assertEquals(0, pcm.data.length);
        assertEquals(0, pcm.frames());
        assertEquals(0.0, pcm.seconds());
        assertEquals(SAMPLE_RATE, pcm.rate);
        assertEquals(SAMPLE_CHANNELS, pcm.channels);
    }

    @Test
    void rejectsEmptyInputAsNotAnOggBitstream() {
        assertEquals("not an Ogg bitstream", decodeFailure(new byte[0]));
    }

    @Test
    void rejectsNonOggBytes() {
        byte[] input = "this is not an Ogg page".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
        assertEquals("not an Ogg bitstream", decodeFailure(input));
    }

    @Test
    void rejectsNullInput() {
        assertThrows(NullPointerException.class, () -> OggVorbis.decode(null));
    }

    @Test
    void rejectsAnOggPageWithAnUnsupportedVersion() {
        byte[] input = oggPage(1, 0x02, 0, TEST_SERIAL, 0, new byte[] { 1, 2, 3 });

        assertEquals("error reading first Ogg page", decodeFailure(input));
    }

    @Test
    void rejectsBosPageContainingNoCompletePacket() {
        byte[] input = oggPage(0, 0x02, 0, TEST_SERIAL, 0, new byte[0]);

        assertEquals("error reading initial header packet", decodeFailure(input));
    }

    @Test
    void rejectsAValidOggPageWhoseFirstPacketIsNotVorbisAudio() {
        byte[] input = oggPage(0, 0x02, 0, TEST_SERIAL, 0, new byte[] { 1, 2, 3 });

        assertEquals("not Vorbis audio data", decodeFailure(input));
    }

    @Test
    void reportsEndOfFileWhenSecondaryHeadersAreMissing() throws IOException {
        byte[] sample = readSample();
        byte[] onlyIdentificationHeaderPage = Arrays.copyOf(sample, endOfPage(sample, 0));

        assertEquals("end of file before all Vorbis headers", decodeFailure(onlyIdentificationHeaderPage));
    }

    @Test
    void rejectsCorruptSecondaryVorbisHeader() throws IOException {
        byte[] corrupt = readSample();
        int secondPageOffset = startOfPage(corrupt, 1);
        int secondPageSegments = corrupt[secondPageOffset + 26] & 0xff;
        int secondPageBody = secondPageOffset + 27 + secondPageSegments;
        int commentPacketLength = corrupt[secondPageOffset + 27] & 0xff;
        int setupPacketOffset = secondPageBody + commentPacketLength;

        // A setup header is packet type 5. Make it an invalid packet type while
        // retaining a valid page checksum so the failure comes from Vorbis
        // header validation rather than Ogg framing.
        corrupt[setupPacketOffset] = 6;
        repairPageChecksum(corrupt, secondPageOffset);

        assertEquals("corrupt secondary Vorbis header", decodeFailure(corrupt));
    }

    private static String decodeFailure(byte[] input) {
        IOException failure = assertThrows(IOException.class, () -> OggVorbis.decode(input));
        assertNotNull(failure.getMessage());
        return failure.getMessage();
    }

    private static byte[] readSample() throws IOException {
        InputStream input = OggVorbisDecodeTests.class.getResourceAsStream(SAMPLE_RESOURCE);
        if (input == null) {
            throw new AssertionError("Missing test resource " + SAMPLE_RESOURCE);
        }
        try (InputStream in = input) {
            return in.readAllBytes();
        }
    }

    private static int startOfPage(byte[] ogg, int pageIndex) {
        int offset = 0;
        for (int page = 0; page < pageIndex; page++) {
            offset += pageLength(ogg, offset);
        }
        return offset;
    }

    private static int endOfPage(byte[] ogg, int pageIndex) {
        int offset = startOfPage(ogg, pageIndex);
        return offset + pageLength(ogg, offset);
    }

    private static int pageLength(byte[] ogg, int offset) {
        if (offset + 27 > ogg.length
                || ogg[offset] != 'O' || ogg[offset + 1] != 'g'
                || ogg[offset + 2] != 'g' || ogg[offset + 3] != 'S') {
            throw new AssertionError("Fixture does not contain an Ogg page at offset " + offset);
        }
        int segmentCount = ogg[offset + 26] & 0xff;
        int headerLength = 27 + segmentCount;
        if (offset + headerLength > ogg.length) {
            throw new AssertionError("Truncated Ogg page header at offset " + offset);
        }
        int bodyLength = 0;
        for (int i = 0; i < segmentCount; i++) {
            bodyLength += ogg[offset + 27 + i] & 0xff;
        }
        if (offset + headerLength + bodyLength > ogg.length) {
            throw new AssertionError("Truncated Ogg page body at offset " + offset);
        }
        return headerLength + bodyLength;
    }

    private static byte[] oggPage(int version, int headerType, long granulePosition,
                                  int serialNumber, int pageSequence, byte[] packet) {
        int segmentCount = packet.length == 0 ? 0 : packet.length / 255 + 1;
        byte[] page = new byte[27 + segmentCount + packet.length];

        page[0] = 'O';
        page[1] = 'g';
        page[2] = 'g';
        page[3] = 'S';
        page[4] = (byte) version;
        page[5] = (byte) headerType;
        putLittleEndian(page, 6, granulePosition, 8);
        putLittleEndian(page, 14, serialNumber, 4);
        putLittleEndian(page, 18, pageSequence, 4);
        page[26] = (byte) segmentCount;

        for (int i = 0; i < segmentCount; i++) {
            page[27 + i] = (byte) Math.min(255, packet.length - i * 255);
        }
        System.arraycopy(packet, 0, page, 27 + segmentCount, packet.length);
        repairPageChecksum(page, 0);
        return page;
    }

    private static void putLittleEndian(byte[] target, int offset, long value, int byteCount) {
        for (int i = 0; i < byteCount; i++) {
            target[offset + i] = (byte) (value >>> (8 * i));
        }
    }

    private static void repairPageChecksum(byte[] ogg, int pageOffset) {
        int length = pageLength(ogg, pageOffset);
        Arrays.fill(ogg, pageOffset + 22, pageOffset + 26, (byte) 0);
        int checksum = oggCrc(ogg, pageOffset, length);
        putLittleEndian(ogg, pageOffset + 22, checksum, 4);
    }

    private static int oggCrc(byte[] data, int offset, int length) {
        int crc = 0;
        for (int i = 0; i < length; i++) {
            crc ^= (data[offset + i] & 0xff) << 24;
            for (int bit = 0; bit < 8; bit++) {
                if ((crc & 0x8000_0000) != 0) {
                    crc = (crc << 1) ^ 0x04c1_1db7;
                } else {
                    crc <<= 1;
                }
            }
        }
        return crc;
    }
}

