    @Test
    void exportsLegacyMeshWithSharedAttributesAndDefaultMaterials() {
        ResContainer model = res(
                layer("vbuf2", vbuf(1, 2, new float[]{1, 2, 3, 4, 5, 6},
                        new float[]{0, 1, 0, 0, 0, 1}, new float[]{0, 0, 1, 1}, null, null)),
                layer("mesh", legacyMesh(1, 5, 0, 1, 1)),
                layer("mesh", legacyMesh(1, 5, 0, 1, 1, 1, 1, 0)));

        GltfExport.Result r = GltfExport.toGlb(model, model, model, "chars/armor.res");
        assertEquals(2, r.vertices, "vertices");
        assertEquals(3, r.triangles, "triangles");
        assertEquals(2, r.submeshes, "submeshes");
        assertEquals(0, r.textures, "textures");

        Glb g = glb(r.glb);
        assertEquals("2.0", map(g.json.get("asset")).get("version"));
        assertEquals("ResForge", map(g.json.get("asset")).get("generator"));
        assertEquals(0, i(g.json.get("scene")));
        assertEquals(List.of(0), ints(map(list(g.json.get("scenes")).get(0)).get("nodes")));

        Map<String, Object> meshNode = map(list(g.json.get("nodes")).get(0));
        assertEquals("armor", meshNode.get("name"), "source path + .res must be stripped");
        assertEquals(0, i(meshNode.get("mesh")));
        assertEquals("armor", map(list(g.json.get("meshes")).get(0)).get("name"));
        assertFalse(g.json.containsKey("skins"));
        assertFalse(g.json.containsKey("animations"));
        assertFalse(g.json.containsKey("textures"));

        Map<String, Object> p0 = primitive(g, 0), p1 = primitive(g, 1);
        assertEquals(List.of("POSITION", "NORMAL", "TEXCOORD_0"),
                new ArrayList<>(map(p0.get("attributes")).keySet()));
        assertEquals(p0.get("attributes"), p1.get("attributes"), "same vbuf -> shared accessors");
        assertEquals(i(p0.get("material")), i(p1.get("material")), "same matid -> one material");
        assertEquals(0, i(p0.get("material")));

        Map<String, Object> pos = accessor(g, map(p0.get("attributes")).get("POSITION"));
        assertEquals("VEC3", pos.get("type"));
        assertEquals(5126, i(pos.get("componentType")));
        assertEquals(2, i(pos.get("count")));
        vec(pos.get("min"), 1, 3, -5);          // (x,y,z) -> (x,z,-y)
        vec(pos.get("max"), 4, 6, -2);
        assertArrayEquals(new float[]{1, 3, -2, 4, 6, -5}, floats(g, map(p0.get("attributes")).get("POSITION")));

        Map<String, Object> nrm = accessor(g, map(p0.get("attributes")).get("NORMAL"));
        assertFalse(nrm.containsKey("min"), "normals need no bounds");
        Map<String, Object> tex = accessor(g, map(p0.get("attributes")).get("TEXCOORD_0"));
        assertEquals("VEC2", tex.get("type"));
        assertEquals(2, i(tex.get("count")));

        assertEquals(6, i(accessor(g, p1.get("indices")).get("count")));
        assertArrayEquals(new int[]{0, 1, 1, 1, 1, 0}, ushorts(g, p1.get("indices")));
        assertNotEquals(i(p0.get("indices")), i(p1.get("indices")));

        List<Object> materials = list(g.json.get("materials"));
        assertEquals(1, materials.size());
        Map<String, Object> mat = map(materials.get(0));
        assertEquals("rfmat_5", mat.get("name"));
        assertEquals(Boolean.TRUE, mat.get("doubleSided"));
        assertEquals("MASK", mat.get("alphaMode"));
        assertEquals(0.5, ((Number) mat.get("alphaCutoff")).doubleValue(), 1e-9f);
        Map<String, Object> pbr = map(mat.get("pbrMetallicRoughness"));
        assertEquals(0.0, ((Number) pbr.get("metallicFactor")).doubleValue(), 1e-9f);
        assertEquals(1.0, ((Number) pbr.get("roughnessFactor")).doubleValue(), 1e-9f);
        assertFalse(pbr.containsKey("baseColorTexture"));

        int bufLen = i(map(list(g.json.get("buffers")).get(0)).get("byteLength"));
        assertTrue(bufLen <= g.bin.length && g.bin.length - bufLen < 4, "buffer length vs padded chunk");
    }

