    @Test
    void skinIncludesInfluenceJointsAndUnweightedSkeletonHelpers() {
        ResContainer model = res(
                layer("vbuf2", vbuf(1, 2, new float[]{0, 0, 0, 0, 1, 0}, null, null,
                        new String[]{"root", "child"}, new int[]{0, 1})),
                layer("mesh", legacyMesh(1, 2, 0, 1, 1)),
                layer("skel", skeleton(
                        bone("root", "", 0, 0, 0),
                        bone("child", "root", 0, 1, 0),
                        bone("helperIK", "root", 0, 2, 0))));

        GltfExport.Result r = GltfExport.toGlb(model, model, model, "rig.res");
        Glb g = glb(r.glb);
        List<Object> nodes = list(g.json.get("nodes"));
        List<Object> skins = list(g.json.get("skins"));
        assertEquals(1, skins.size());
        Map<String, Object> skin = map(skins.get(0));

        assertEquals(List.of(1, 2, 3), ints(skin.get("joints")),
                "influence order first, then remaining skeleton bones");
        Map<String, Object> meshNode = map(nodes.get(0));
        assertEquals(0, i(meshNode.get("skin")));

        assertEquals(4, i(skin.get("skeleton")));
        Map<String, Object> rootNode = map(nodes.get(4));
        assertEquals("ROOT", rootNode.get("name"));
        assertEquals(List.of(1), ints(rootNode.get("children")));
        assertEquals(List.of(0, 4, 5), ints(map(list(g.json.get("scenes")).get(0)).get("nodes")));

        Map<String, Object> marker = map(nodes.get(5));
        assertEquals("ResForgeSkeletonBasis_pretty_v2", marker.get("name"));
        vec(marker.get("scale"), 0, 0, 0);
        assertEquals("pretty-v2", map(g.json.get("extras")).get("resforgeSkeletonBasis"));

        assertEquals("root", map(nodes.get(1)).get("name"));
        assertEquals(4, list(map(nodes.get(1)).get("rotation")).size());
        assertEquals(4, list(map(map(nodes.get(1)).get("extras")).get("resforgeBoneBasis")).size());

        Map<String, Object> ibmAcc = accessor(g, skin.get("inverseBindMatrices"));
        assertEquals("MAT4", ibmAcc.get("type"));
        assertEquals(3, i(ibmAcc.get("count")));
        float[] ibm = floats(g, skin.get("inverseBindMatrices"));
        assertEquals(0f, ibm[12], 1e-5f, "root bone sits at the origin");
        assertEquals(0f, ibm[13], 1e-5f);
        assertEquals(0f, ibm[14], 1e-5f);
        assertTrue(Math.abs(ibm[16 + 12]) + Math.abs(ibm[16 + 13]) + Math.abs(ibm[16 + 14]) > 0.5,
                "child inverse bind matrix carries an offset");
        assertEquals(0f, ibm[3], 1e-6f);
        assertEquals(1f, ibm[15], 1e-6f);
    }

