        w.uint8(0).uint16(3).string("pos");
        for (int i = 0; i < 9; i++) w.float32(0);
        w.string("nrm");
        for (int i = 0; i < 9; i++) w.float32(0);
        w.string("tex");
        for (int i = 0; i < 6; i++) w.float32(0);
