        Glb g = new Glb();
        int pos = g.floats(new float[]{0, 0, 0, 1, 0, 0, 0, 1, 0}, 3);
        int nrm = g.floats(new float[]{0, 0, 1, 0, 0, 1, 0, 0, 1}, 3);
        int tex = g.floats(new float[]{0, 0, 1, 0, 0, 1}, 2);
        int idx = g.ushorts(new int[]{0, 1, 2});
        byte[] glb = g.build(
                "[{\"primitives\":[{\"attributes\":{\"POSITION\":" + pos + ",\"NORMAL\":" + nrm
                        + ",\"TEXCOORD_0\":" + tex + "},\"indices\":" + idx + "}]}]",
                "[{\"mesh\":0}]");

