        Vbuf2Codec vbuf = Vbuf2Codec.parse(layerNamed(roundTrip(r.res), "vbuf2").data);
        float[] tan = vbuf.decodeAttr("tan");
        float[] bit = vbuf.decodeAttr("bit");
        assertNotNull(tan);
        assertNotNull(bit);
        assertArrayEquals(tan, bit, 1e-6f);
        float[] n = vbuf.decodeAttr("nrm");
        for (int v = 0; v < 3; v++) {
            double len = Math.sqrt(tan[v * 3] * tan[v * 3] + tan[v * 3 + 1] * tan[v * 3 + 1]
                    + tan[v * 3 + 2] * tan[v * 3 + 2]);
            assertEquals(1.0, len, 1e-5);
            double dot = tan[v * 3] * n[v * 3] + tan[v * 3 + 1] * n[v * 3 + 1]
                    + tan[v * 3 + 2] * n[v * 3 + 2];
            assertEquals(0.0, dot, 1e-5);
        }
    }

