package resforge.model;

import org.junit.jupiter.api.Test;
import resforge.io.MessageWriter;
import resforge.layers.MeshAnimInfo;
import resforge.layers.MeshInfo;
import resforge.res.Layer;
import resforge.res.ResContainer;
import resforge.vbuf.Vbuf2Codec;
import resforge.model.Vbuf2Data;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/** Behavioural tests for {@link GltfImport#rebuild(byte[], byte[])}. */
class GltfImportRebuildTests {

    /* ------------------------------------------------------------------ helpers */

    private static byte[] res(Layer... layers) {
        ResContainer c = new ResContainer(1);
        for (Layer l : layers) c.layers.add(l);
        return c.serialize();
    }

    private static Layer layer(String name, byte[] data) {
        return new Layer(name, data);
    }

    /** A ver-0 vbuf2 with one or more bare float32 attributes. */
    private static byte[] bareVbuf(int num, Object... nameAndValues) {
        MessageWriter w = new MessageWriter();
        w.uint8(0).uint16(num);
        for (int i = 0; i < nameAndValues.length; i += 2) {
            w.string((String) nameAndValues[i]);
            float[] vals = (float[]) nameAndValues[i + 1];
            for (float v : vals) w.float32(v);
        }
        return w.toByteArray();
    }

    /** A ver-1 vbuf2 with formatted attributes (attribute name -> sub-buffer bytes). */
    private static byte[] formattedVbuf(int id, int num, Map<String, byte[]> attrs) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(id).uint16(num);
        for (Map.Entry<String, byte[]> e : attrs.entrySet()) {
            w.string(e.getKey()).int32(e.getValue().length).bytes(e.getValue());
        }
        return w.toByteArray();
    }

    private static byte[] f4(float... vals) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).string("f4");
        for (float v : vals) w.float32(v);
        return w.toByteArray();
    }

    /** bones2 sub-buffer: every vertex fully weighted to the single bone "root". */
    private static byte[] bones2SingleRoot(int num) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).string("f4").uint8(1);      // data version, weight format, max influences
        w.string("root");
        w.uint16(num).uint16(0);               // run count, first vertex
        for (int i = 0; i < num; i++) w.float32(1f);
        w.uint16(0).uint16(0);                 // end of this bone's spans
        w.string("");                          // end of bone list
        return w.toByteArray();
    }

    /** A manim layer with fmt-3 frames, each moving one vertex by a half-float delta. */
    private static byte[] manim(float len, float[] times, int[] vertices, float[][] deltas) {
        MessageWriter w = new MessageWriter();
        w.uint8(1).int16(3).uint8(0).float32(len);
        for (int i = 0; i < times.length; i++) {
            w.uint8(3).float32(times[i]).uint16(1);
            w.uint16(vertices[i]).uint16(1);
            w.float16(deltas[i][0]).float16(deltas[i][1]).float16(deltas[i][2]);
        }
        w.uint8(0);
        return w.toByteArray();
    }

    /** Old-form FastMesh: flags=16 (vbufid present), uint16 tri count, int16 matid, int16 vbufid, indices. */
    private static byte[] oldMesh(int matid, int vbufid, int... tris) {
        MessageWriter w = new MessageWriter();
        w.uint8(16).uint16(tris.length / 3).int16(matid).int16(vbufid);
        for (int t : tris) w.uint16(t);
        return w.toByteArray();
    }

    private static ResContainer roundTrip(byte[] raw) {
        return ResContainer.parse(raw);
    }

    private static Layer layerNamed(ResContainer c, String name) {
        for (Layer l : c.layers) if (l.name.equals(name)) return l;
        fail("no layer named " + name + " in " + names(c));
        return null;
