    private static List<Layer> layersNamed(ResContainer c, String name) {
        List<Layer> out = new ArrayList<>();
        for (Layer l : c.layers) if (l.name.equals(name)) out.add(l);
        return out;
    }

    private static List<String> names(ResContainer c) {
        List<String> n = new ArrayList<>();
        for (Layer l : c.layers) n.add(l.name);
        return n;
