    /* --------------------------------------------------------------- GLB builder */

    private static final class Glb {
        private final ByteArrayOutputStream bin = new ByteArrayOutputStream();
        private final StringBuilder accessors = new StringBuilder();
        private final StringBuilder views = new StringBuilder();
        private final StringBuilder materials = new StringBuilder();
        private int accessorCount, viewCount, materialCount;

        int material(String name) {
            if (materialCount > 0) materials.append(',');
            materials.append("{\"name\":\"").append(name).append("\"}");
            return materialCount++;
        }

        private int addView(byte[] data) {
            while (bin.size() % 4 != 0) bin.write(0);
            int off = bin.size();
            bin.write(data, 0, data.length);
            if (viewCount > 0) views.append(',');
            views.append("{\"buffer\":0,\"byteOffset\":").append(off)
                    .append(",\"byteLength\":").append(data.length).append('}');
            return viewCount++;
        }

        private int addAccessor(String json) {
            if (accessorCount > 0) accessors.append(',');
            accessors.append(json);
            return accessorCount++;
        }

        private static String type(int comps) {
            return switch (comps) {
                case 1 -> "SCALAR";
                case 2 -> "VEC2";
                case 3 -> "VEC3";
                default -> "VEC4";
            };
        }

        int floats(float[] data, int comps) {
            MessageWriter w = new MessageWriter();
            for (float v : data) w.float32(v);
            int v = addView(w.toByteArray());
            return addAccessor("{\"bufferView\":" + v + ",\"componentType\":5126,\"count\":"
                    + (data.length / comps) + ",\"type\":\"" + type(comps) + "\"}");
        }

        /** All-zero accessor: no bufferView is legal and keeps huge counts cheap. */
        int zeroFloats(int count, int comps) {
            return addAccessor("{\"componentType\":5126,\"count\":" + count
                    + ",\"type\":\"" + type(comps) + "\"}");
        }

        int ushorts(int[] data) {
            MessageWriter w = new MessageWriter();
            for (int v : data) w.uint16(v);
            int v = addView(w.toByteArray());
            return addAccessor("{\"bufferView\":" + v + ",\"componentType\":5123,\"count\":"
                    + data.length + ",\"type\":\"SCALAR\"}");
        }

        int ubytes4(int[] data) {
            MessageWriter w = new MessageWriter();
            for (int v : data) w.uint8(v);
            int v = addView(w.toByteArray());
            return addAccessor("{\"bufferView\":" + v + ",\"componentType\":5121,\"count\":"
                    + (data.length / 4) + ",\"type\":\"VEC4\"}");
        }

        byte[] build(String meshes, String nodes) {
            return build(meshes, nodes, "[{\"nodes\":[0]}]", null);
        }

        byte[] build(String meshes, String nodes, String scenes, String skins) {
            StringBuilder json = new StringBuilder("{");
            json.append("\"asset\":{\"version\":\"2.0\"},");
            json.append("\"accessors\":[").append(accessors).append("],");
            json.append("\"bufferViews\":[").append(views).append("],");
            if (materialCount > 0) json.append("\"materials\":[").append(materials).append("],");
            json.append("\"buffers\":[{\"byteLength\":").append(bin.size()).append("}],");
            json.append("\"meshes\":").append(meshes).append(',');
            json.append("\"nodes\":").append(nodes).append(',');
            json.append("\"scenes\":").append(scenes).append(',');
            json.append("\"scene\":0");
            if (skins != null) json.append(",\"skins\":").append(skins);
            json.append('}');

            byte[] jsonBytes = utf8(json.toString());
            int jsonPadded = (jsonBytes.length + 3) & ~3;
            byte[] binBytes = bin.toByteArray();
            int binPadded = (binBytes.length + 3) & ~3;
            int total = 12 + 8 + jsonPadded + 8 + binPadded;
            java.nio.ByteBuffer bb = java.nio.ByteBuffer.allocate(total)
                    .order(java.nio.ByteOrder.LITTLE_ENDIAN);
            bb.putInt(0x46546C67).putInt(2).putInt(total);
            bb.putInt(jsonPadded).putInt(0x4E4F534A);
            bb.put(jsonBytes);
            for (int i = jsonBytes.length; i < jsonPadded; i++) bb.put((byte) ' ');
            bb.putInt(binPadded).putInt(0x004E4942);
            bb.put(binBytes);
            for (int i = binBytes.length; i < binPadded; i++) bb.put((byte) 0);
            return bb.array();
        }
    }

