        GltfImport.RebuildResult r = GltfImport.rebuild(orig, glb);

        Vbuf2Codec vbuf = Vbuf2Codec.parse(layerNamed(roundTrip(r.res), "vbuf2").data);
        float[] tan = vbuf.decodeAttr("tan");
        float[] bit = vbuf.decodeAttr("bit");
        assertNotNull(tan);
        assertNotNull(bit);
        assertArrayEquals(tan, bit, 1e-6f);
        float[] n = vbuf.decodeAttr("nrm");
        for (int v = 0; v < 3; v++) {
            double len = Math.sqrt(tan[v * 3] * tan[v * 3] + tan[v * 3 + 1] * tan[v * 3 + 1]
                    + tan[v * 3 + 2] * tan[v * 3 + 2]);
            assertEquals(1.0, len, 1e-5);
            double dot = tan[v * 3] * n[v * 3] + tan[v * 3 + 1] * n[v * 3 + 1]
                    + tan[v * 3 + 2] * n[v * 3 + 2];
            assertEquals(0.0, dot, 1e-5);
        }
    }

    /* -------------------------------------------------------------------- morphs */

    @Test
    void reencodesManimAtTheRebuiltVertexCount() {
        byte[] orig = res(
                layer("vbuf2", bareVbuf(3, "pos", new float[]{0, 0, 0, 1, 0, 0, 0, 1, 0})),
                layer("mesh", oldMesh(1, 0, 0, 1, 2)),
                layer("manim", manim(1f,
                        new float[]{0.25f, 0.5f}, new int[]{0, 1},
                        new float[][]{{1, 0, 0}, {0, 1, 0}})));
        Glb g = new Glb();
        int pos = g.floats(new float[]{0, 0, 0, 1, 0, 0, 0, 1, 0}, 3);
        int t0 = g.floats(new float[]{1, 0, 0, 0, 0, 0, 0, 0, 0}, 3);
        int t1 = g.floats(new float[]{0, 0, 0, 0, 1, 0, 0, 0, 0}, 3);
        byte[] glb = g.build(
                "[{\"primitives\":[{\"attributes\":{\"POSITION\":" + pos + "},"
                        + "\"targets\":[{\"POSITION\":" + t0 + "},{\"POSITION\":" + t1 + "}]}]}]",
                "[{\"mesh\":0}]");

        GltfImport.RebuildResult r = GltfImport.rebuild(orig, glb);

        MeshAnimInfo out = MeshAnimInfo.parse(layerNamed(roundTrip(r.res), "manim").data);
        assertTrue(out.recognized);
        assertEquals(2, out.frames.size());
        assertEquals(0.25f, out.frames.get(0).time, 1e-6f);
        assertEquals(0.5f, out.frames.get(1).time, 1e-6f);
        assertEquals(1, out.frames.get(0).vertices);
        assertEquals(0, out.frames.get(0).idx[0]);
        assertArrayEquals(new float[]{1, 0, 0}, out.frames.get(0).pos, 1e-6f);
        assertEquals(1, out.frames.get(1).vertices);
        assertEquals(1, out.frames.get(1).idx[0]);
        assertArrayEquals(new float[]{0, 0, 1}, out.frames.get(1).pos, 1e-6f);
    }

    @Test
    void rejectsMorphFrameCountMismatch() {
        byte[] orig = res(
                layer("vbuf2", bareVbuf(3, "pos", new float[]{0, 0, 0, 1, 0, 0, 0, 1, 0})),
                layer("mesh", oldMesh(1, 0, 0, 1, 2)),
                layer("manim", manim(1f, new float[]{0.5f}, new int[]{0}, new float[][]{{1, 0, 0}})));
        Glb g = new Glb();
        int pos = g.floats(new float[]{0, 0, 0, 1, 0, 0, 0, 1, 0}, 3);
        int t0 = g.floats(new float[]{1, 0, 0, 0, 0, 0, 0, 0, 0}, 3);
        int t1 = g.floats(new float[]{0, 1, 0, 0, 0, 0, 0, 0, 0}, 3);
        byte[] glb = g.build(
                "[{\"primitives\":[{\"attributes\":{\"POSITION\":" + pos + "},"
                        + "\"targets\":[{\"POSITION\":" + t0 + "},{\"POSITION\":" + t1 + "}]}]}]",
                "[{\"mesh\":0}]");

        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
